def check_f(f_dict, max_val):
    # f_dict is a dictionary mapping (x, y) to f(x, y)
    # Check if f is a bijection to {0, 1, ..., max_val}
    vals = list(f_dict.values())
    if sorted(vals) != list(range(max_val + 1)):
        return False
    # Check the property
    for (x1, y1), v1 in f_dict.items():
        for (x2, y2), v2 in f_dict.items():
            if v1 > v2:
                # Check x+1
                if (x1 + 1, y1) in f_dict and (x2 + 1, y2) in f_dict:
                    if f_dict[(x1 + 1, y1)] <= f_dict[(x2 + 1, y2)]:
                        return False
                # Check y+1
                if (x1, y1 + 1) in f_dict and (x2, y2 + 1) in f_dict:
                    if f_dict[(x1, y1 + 1)] <= f_dict[(x2, y2 + 1)]:
                        return False
    return True

